from typing import Annotated, Union, get_origin, get_args
from pydantic import BaseModel

# Simulate the fix
from fastapi._compat import _annotation_is_complex, field_annotation_is_complex as original

def field_annotation_is_complex_fixed(annotation):
    origin = get_origin(annotation)
    if origin is Union or origin is type(Union):
        return any(field_annotation_is_complex_fixed(arg) for arg in get_args(annotation))
    if origin is Annotated:
        return field_annotation_is_complex_fixed(get_args(annotation)[0])
    return (
        _annotation_is_complex(annotation)
        or _annotation_is_complex(origin)
        or hasattr(origin, '__pydantic_core_schema__')
        or hasattr(origin, '__get_pydantic_core_schema__')
    )

class Pie(BaseModel):
    pass

t = Annotated[Pie, 'tag']
print('Annotated[Pie, tag] is complex:', field_annotation_is_complex_fixed(t))

# Union of Annotated
from typing import Union as UnionType
t2 = Annotated[Pie, 'tag1'] | Annotated[Pie, 'tag2']
print('Union of Annotated is complex:', field_annotation_is_complex_fixed(t2))
""}

